head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.trigger2_onclick = function(e) {
	imports("uiplugin.popup");
	WebSquare.util.openPopup("/sample/common_link/p_popup_useControl_WPF-1871_(WSQ-2972)_pop.xml", {
		id: "pop1",
		type: "litewindow",
		width: 500,
		minimumWidth: 100,
		height: 500,
		top: 50,
		left: 50,
		popupName: "test",
		modal: true,
		useIFrame: false,
		resizable: true,
		status: false,
		menubar: false,
		scrollbars: scroll,
		title: 'test222',
		useMaxmimize: true,
		useControl: true,
		controls: {
			minimize: true,
			maximize: true,
			close: false
		},
		foldSize: {
			width: 200
		},
		foldOnMinimized: true
	});
};

scwin.getStyleEle = function(id, style) {
	var el = scwin.__getDom(id),
		eleStyle = window.getComputedStyle(el);
	return eleStyle.getPropertyValue(style);
};

scwin.checktype1 = function() {
	return typeof pop1;
};

scwin.checktype2 = function() {
	return typeof pop1_header_control;
};

scwin.checkVal = function() {
	return window.getComputedStyle((document.getElementById('pop1_header_control') || document.getElementById('mf_pop1_header_control'))).getPropertyValue('width') == "40px";
};
